    (21, '2026-0021', 4, 'Gamification in Special Education', 'Undergraduate', 'Undetermined', 'Type of Review', '2026-10-12', NULL, NULL, '2026-10-07 12:10:52.517176', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0021", "study_title": "Gamification in Special Education", "description_study": "1. Design and pilot-test gamified mobile learning applications for children diagnosed with mild-to-moderate learning disabilities.\n2. Measure learner engagement, task persistence, and knowledge retention across foundational literacy and numeracy modules.\n3. Gather special education teacher evaluations on instructional usability and individual education plan (IEP) alignment.", "description_objectives": "1. Design and pilot-test gamified mobile learning applications for children diagnosed with mild-to-moderate learning disabilities.\n2. Measure learner engagement, task persistence, and knowledge retention across foundational literacy and numeracy modules.\n3. Gather special education teacher evaluations on instructional usability and individual education plan (IEP) alignment."}', 1, FALSE),
