    (58, '2026-0058', 5, 'Impact of Noise Pollution on the Cognitive Development of Children in Urban Centers', 'Faculty', 'Undetermined', 'Type of Review', '2026-07-07', '2026-07-28', NULL, '2026-10-07 14:42:25.04128', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0058", "study_title": "Impact of Noise Pollution on the Cognitive Development of Children in Urban Centers", "description_study": "1. Measure ambient acoustic noise levels across elementary school zones situated along high-traffic urban corridors in Zamboanga City.\n2. Assess cognitive performance, reading comprehension, and sustained attention metrics among primary school pupils in high-noise versus low-noise classrooms.\n3. Provide environmental and architectural acoustic mitigation guidelines for urban public school infrastructure.", "description_objectives": "1. Measure ambient acoustic noise levels across elementary school zones situated along high-traffic urban corridors in Zamboanga City.\n2. Assess cognitive performance, reading comprehension, and sustained attention metrics among primary school pupils in high-noise versus low-noise classrooms.\n3. Provide environmental and architectural acoustic mitigation guidelines for urban public school infrastructure."}', 1, FALSE),
    (59, '2026-0059', 5, 'The Efficacy of Community-led Interventions in Reducing Teenage Pregnancy Rates', 'Faculty', 'Undetermined', 'Type of Review', '2026-07-07', '2026-07-28', NULL, '2026-10-07 14:42:25.04128', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0059", "study_title": "The Efficacy of Community-led Interventions in Reducing Teenage Pregnancy Rates", "description_study": "1. Evaluate the effectiveness of community-driven peer education and adolescent reproductive health workshops in lowering teenage pregnancy incidence.\n2. Measure changes in reproductive health literacy, contraceptive perceptions, and health-seeking behaviors among youth participants over 12 months.\n3. Formulate sustainable community-based implementation guidelines for local youth councils (Sangguniang Kabataan).", "description_objectives": "1. Evaluate the effectiveness of community-driven peer education and adolescent reproductive health workshops in lowering teenage pregnancy incidence.\n2. Measure changes in reproductive health literacy, contraceptive perceptions, and health-seeking behaviors among youth participants over 12 months.\n3. Formulate sustainable community-based implementation guidelines for local youth councils (Sangguniang Kabataan)."}', 1, FALSE),
    (60, '2026-0060', 8, 'Perceived Stress and Coping Mechanisms of Medical Interns in Tertiary Hospitals', 'Faculty', 'Undetermined', 'Type of Review', '2026-08-03', '2026-08-24', NULL, '2026-10-07 14:42:25.04128', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0060", "study_title": "Perceived Stress and Coping Mechanisms of Medical Interns in Tertiary Hospitals", "description_study": "1. Quantify perceived occupational stress and burnout levels among medical interns during clinical rotations in regional tertiary hospitals.\n2. Identify the predominant adaptive and maladaptive coping mechanisms utilized by trainees during extended on-call shifts.\n3. Formulate institutional wellness interventions and duty-hour policy recommendations to alleviate psychological distress.", "description_objectives": "1. Quantify perceived occupational stress and burnout levels among medical interns during clinical rotations in regional tertiary hospitals.\n2. Identify the predominant adaptive and maladaptive coping mechanisms utilized by trainees during extended on-call shifts.\n3. Formulate institutional wellness interventions and duty-hour policy recommendations to alleviate psychological distress."}', 1, FALSE),
    (61, '2026-0061', 8, 'Evaluating the Implementation of the Universal Health Care Law at the Local Government Level', 'Faculty', 'Undetermined', 'Type of Review', '2026-08-03', '2026-08-24', NULL, '2026-10-07 14:42:25.04128', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0061", "study_title": "Evaluating the Implementation of the Universal Health Care Law at the Local Government Level", "description_study": "1. Evaluate the implementation fidelity and operational milestones of the Universal Health Care Law (RA 11223) across local government units in Region IX.\n2. Assess primary healthcare service integration, drug availability, and community referral network performance at the barangay level.\n3. Identify fiscal and human resource bottlenecks to formulate sustainable municipal healthcare financing models.", "description_objectives": "1. Evaluate the implementation fidelity and operational milestones of the Universal Health Care Law (RA 11223) across local government units in Region IX.\n2. Assess primary healthcare service integration, drug availability, and community referral network performance at the barangay level.\n3. Identify fiscal and human resource bottlenecks to formulate sustainable municipal healthcare financing models."}', 1, FALSE),
    (62, '2026-0062', 8, 'Antibiotic Resistance Patterns in Common Pathogens Isolated from Clinical Samples', 'Faculty', 'Undetermined', 'Type of Review', '2026-08-03', '2026-08-24', NULL, '2026-10-07 14:42:25.04128', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0062", "study_title": "Antibiotic Resistance Patterns in Common Pathogens Isolated from Clinical Samples", "description_study": "1. Determine the phenotypic and genotypic antimicrobial resistance profiles of clinical pathogens (S. aureus, E. coli, K. pneumoniae) isolated from tertiary hospital samples.\n2. Characterize the prevalence of extended-spectrum beta-lactamase (ESBL) and carbapenem-resistant Enterobacteriaceae (CRE).\n3. Develop evidence-based institutional antibiogram recommendations to optimize empirical antimicrobial stewardship.", "description_objectives": "1. Determine the phenotypic and genotypic antimicrobial resistance profiles of clinical pathogens (S. aureus, E. coli, K. pneumoniae) isolated from tertiary hospital samples.\n2. Characterize the prevalence of extended-spectrum beta-lactamase (ESBL) and carbapenem-resistant Enterobacteriaceae (CRE).\n3. Develop evidence-based institutional antibiogram recommendations to optimize empirical antimicrobial stewardship."}', 1, FALSE),
