    (74, '2026-0074', 3, 'Nutritional Interventions for Anemia among Pregnant Women in Rural Clinics', 'Faculty', 'Undetermined', 'Type of Review', '2026-09-12', '2026-09-29', NULL, '2026-10-07 14:42:25.04128', '2026-10-18 16:08:30.625549', '{"rec_code": "2026-0074", "study_title": "Nutritional Interventions for Anemia among Pregnant Women in Rural Clinics", "description_study": "1. Assess the prevalence and clinical severity of iron-deficiency anemia among pregnant women attending rural health clinics in Western Mindanao.\n2. Evaluate adherence rates and therapeutic outcomes of localized oral iron supplementation coupled with community nutrition education.\n3. Compare maternal hemoglobin levels and neonatal birth weight profiles across the intervention cohort.", "description_objectives": "1. Assess the prevalence and clinical severity of iron-deficiency anemia among pregnant women attending rural health clinics in Western Mindanao.\n2. Evaluate adherence rates and therapeutic outcomes of localized oral iron supplementation coupled with community nutrition education.\n3. Compare maternal hemoglobin levels and neonatal birth weight profiles across the intervention cohort."}', 1, FALSE),
