    (109, '2026-0089', 8, 'Clinical Efficacy and Safety of Standardized Morinda citrifolia (Noni) Botanical Extract Adjunct in Mild-to-Moderate Diabetic Peripheral Neuropathy: A Randomized, Double-Blind, Placebo-Controlled Trial in Western Mindanao', 'Undergraduate', 'Full Board', 'Clearance Granted', '2026-09-10', '2026-10-18', '2026-10-18', '2026-10-18 13:51:28.327306', '2026-10-18 14:45:17.738927', '{"or_number": "OR-2026-9908", "study_details": {"title": "Clinical Efficacy and Safety of Standardized Morinda citrifolia (Noni) Botanical Extract Adjunct in Mild-to-Moderate Diabetic Peripheral Neuropathy: A Randomized, Double-Blind, Placebo-Controlled Trial in Western Mindanao", "study_site": "Outpatient Endocrinology Clinic, Zamboanga City Medical Center (ZCMC)", "duration_months": 12, "brief_description": "A 16-week randomized, double-blind, placebo-controlled trial evaluating standardized Morinda citrifolia botanical extract as an adjunctive therapy for diabetic peripheral neuropathy among 120 adult patients in Zamboanga City.", "target_population": "Adults aged 18-70 with diagnosed Type 2 Diabetes Mellitus and documented mild-to-moderate distal symmetric polyneuropathy.", "primary_objectives": "Evaluate the reduction of neuropathic symptoms via Total Neuropathy Score (TNS) and assess clinical tolerability."}, "submission_date": "2026-09-20", "applicant_profile": {"name": "Applicant User", "email": "applicant@adzu.edu.ph", "phone": "09171234567", "department": "College of Science and Information Technology", "affiliation": "Internal"}, "clearance_details": {"chair_name": "Ethics Chair", "granted_at": "2026-10-18T16:45:17+02:00", "validity_end": "2027-10-17", "validity_start": "2026-10-18", "certificate_number": "AdZU-REC-2026-0089", "issued_by_admin_id": 2, "validity_period_years": 1, "verification_checklist": {"dir-f11_risksToParticipants": {"status": "Satisfied", "evaluator_remarks": ""}, "dir-f11_riskMitigationMeasures": {"status": "Satisfied", "evaluator_rema