    (47, 106, 3, 'Primary Reviewer', 'Completed', 'Approved', 'The tele-psychiatry protocol addresses critical mental health disparities among internally displaced communities. The digital data security and encrypted psychiatric follow-up are adequately established. Recommended for approval.', '2026-09-30', '2026-10-17', '2026-10-18 03:57:52.635245', '{"form11": {"metadata": {"recFormNo": "11", "versionNo": "16"}, "guideQuestions": {"socialValue": {"comment": "Addresses critical shortage of psychiatric specialists in rural displaced communities.", "response": "Yes"}, "vulnerabilityIssue": {"comment": "Displaced migrant population is inherently vulnerable, but adequate community safeguards are established.", "response": "Yes"}, "risksToParticipants": {"comment": "Risks of adverse psychotropic reactions are minimal to moderate, managed by weekly telephonic check-ins.", "response": "Yes"}, "otherConcernsComment": "Excellent community initiative. Recommend ethical approval.", "studyObjectivesSmart": {"comment": "", "response": "Yes"}, "riskMitigationMeasures": {"comment": "Local MHO transport referral pathways provide acceptable safety coverage.", "response": "Yes"}, "informedConsentAdequate": {"comment": "", "response": "Yes"}, "studyBackgroundAdequate": {"comment": "", "response": "Yes"}, "humanParticipantsRequired": {"comment": "", "response": "Yes"}, "researchDesignAppropriate": {"comment": "Hybrid cohort design is robust and well suited for displaced populations.", "sampleSizeJustified": {"response": "Satisfactory"}, "dataAnalysisPlanAndDummyTables": {"response": "Satisfactory"}, "populationIdentifiedAndDefined": {"response": "Satisfactory"}, "selectionOfParticipantsDescribed": {"response": "Satisfactory"}}, "researchFacilitiesAdequate": {"comment": "", "response": "Yes"}, "conflictOfInterestDisclosure": {"comment": "", "response": "Yes"}, "investigatorsAdequatelyTrained": {"comment": "Dr. Soriano-Uy has board certification in psychiatry and GCP certification.", "response": "Yes"}, "vulnerabilityMechanismsInPlace": {"comment": "Bilingual community health workers assist in facilitating tele-consultations.", "response": "Yes"}, "researchQuestionsSupportedByLiterature": {"comment": "", "response": "Yes"}}, "recommendations": {"decision": "Approved", "disapprovedReasons": "", "majorRevisionComments": "", "minorRevisionsComments": ""}}, "form12": {"metadata": {"recFormNo": "12", "versionNo": "16"}, "guideQuestions": {"informedConsentNecessity": {"ifNoExplanation": "", "necessaryToSeekConsent": "Yes"}, "sufficientInformationChecklist": {"purposeOfStudy": "Yes", "otherConcernsComments": "Consent forms are clearly worded and respectful of cultural sensitivities.", "benefitsToParticipants": "Yes", "extentOfConfidentiality": "Yes", "proceduresToBeCarriedOut": "Yes", "discomfortsAndInconveniences": "Yes", "risksIncludingDiscrimination": "Yes", "expectedDurationOfParticipation": "Yes", "alternativeTreatmentsOrProcedures": "Not Applicable", "randomAssignmentToTrialTreatments": "Not Applicable", "adequateProcessForVoluntaryConsent": "Yes", "refusalOrDiscontinuanceWithoutPenalty": "Yes", "writtenInSimpleUnderstandableLanguage": "Yes", "compensationOrMedicalTreatmentsForInjury": "Yes", "contactPersonForQuestionsAndInjuryAssistance": "Yes"}}, "recommendations": {"decision": "Approved", "disapprovedReasons": "", "majorRevisionComments": "", "minorRevisionsComments": ""}}}', 1),
    (48, 106, 4, 'Non-Primary Reviewer', 'Completed', 'Minor Revisions', 'Tele-mental health consent must be adapted for low-literacy participants. Provide audio-visual or pictorial consent explanation in Sinama/Tausug and clarify cloud server data encryption standards.', '2026-09-30', '2026-10-17', '2026-10-18 03:57:52.635245', '{"form12": {"metadata": {"recFormNo": "12", "versionNo": "16"}, "guideQuestions": {"informedConsentNecessity": {"ifNoExplanation": "", "necessaryToSeekConsent": "Yes"}, "sufficientInformationChecklist": {"purposeOfStudy": "Yes", "otherConcernsComments": "Tele-mental health consent must be adapted for low-literacy participants. Provide audio-visual or pictorial consent explanation in Sinama/Tausug and clarify cloud server data encryption standards.", "benefitsToParticipants": "Yes", "extentOfConfidentiality": "No", "proceduresToBeCarriedOut": "Yes", "discomfortsAndInconveniences": "Yes", "risksIncludingDiscrimination": "Yes", "expectedDurationOfParticipation": "Yes", "alternativeTreatmentsOrProcedures": "Not Applicable", "randomAssignmentToTrialTreatments": "Not Applicable", "adequateProcessForVoluntaryConsent": "Yes", "refusalOrDiscontinuanceWithoutPenalty": "Yes", "writtenInSimpleUnderstandableLanguage": "No", "compensationOrMedicalTreatmentsForInjury": "Yes", "contactPersonForQuestionsAndInjuryAssistance": "Yes"}}, "recommendations": {"decision": "Minor Revisions", "disapprovedReasons": "", "majorRevisionComments": "", "minorRevisionsComments": "1. Translate consent form into colloquial Tausug at 6th-grade reading level. 2. Clarify whether cloud-recorded tele-consultation video clips will be permanently deleted after transcription."}}}', 1),
    (49, 106, 5, 'Primary Reviewer', 'Completed', 'Disapproved', 'High risk of adverse psychiatric crises. Dispensing scheduled psychotropic medications remotely to displaced vulnerable individuals without an on-the-ground psychiatric crisis intervention team violates patient safety standards. Study cannot proceed in its current format; Disapproval recommended.', '2026-09-30', '2026-10-17', '2026-10-18 03:57:52.635245', '{"form11": {"metadata": {"recFormNo": "11", "versionNo": "16"}, "guideQuestions": {"socialValue": {"comment": "Scientific premise is valid, but the ethical safety architecture is fundamentally compromised.", "response": "Yes"}, "vulnerabilityIssue": {"comment": "Highly vulnerable displaced population experiencing acute post-conflict trauma.", "response": "Yes"}, "risksToParticipants": {"comment": "Remote prescribing of scheduled psychotropics without local psychiatric emergency facility partnership poses imminent patient safety hazard.", "response": "Unable To Assess"}, "otherConcernsComment": "Unacceptable participant risks without a dedicated field psychiatrist.", "studyObjectivesSmart": {"comment": "", "response": "Yes"}, "riskMitigationMeasures": {"comment": "No licensed psychiatrist physically present in Zamboanga Sibugay field sites during adverse drug reactions or acute suicidal ideation.", "response": "No"}, "informedConsentAdequate": {"comment": "Does not explain paradoxical drug effects, dependence risks, or neuroleptic malignant syndrome.", "response": "No"}, "studyBackgroundAdequate": {"comment": "", "response": "Yes"}, "humanParticipantsRequired": {"comment": "", "response": "Yes"}, "researchDesignAppropriate": {"comment": "Lacks safety stopping rules for drug-induced psychosis or acute extrapyramidal reactions.", "sampleSizeJustified": {"response": "Satisfactory"}, "dataAnalysisPlanAndDummyTables": {"response": "Unable To Assess"}, "populationIdentifiedAndDefined": {"response": "Satisfactory"}, "selectionOfParticipantsDescribed": {"response": "Satisfactory"}}, "researchFacilitiesAdequate": {"comment": "Remote evacuation evacuation camps lack reliable electric grid and secure medicine storage refrigerators.", "response": "No"}, "conflictOfInterestDisclosure": {"comment": "", "response": "Yes"}, "investigatorsAdequatelyTrained": {"comment": "", "response": "Yes"}, "vulnerabilityMechanismsInPlace": {"comment": "Protection against clinical exploitation and adverse psychiatric events is severely deficient.", "response": "No"}, "researchQuestionsSupportedByLiterature": {"comment": "", "response": "Yes"}}, "recommendations": {"decision": "Disapproved", "disapprovedReasons": "Dispensing psychotropic medications remotely to displaced vulnerable individuals without an on-the-ground psychiatric crisis intervention team violates patient safety standards. Study cannot proceed in its current format; Disapproval recommended.", "majorRevisionComments": "", "minorRevisionsComments": ""}}, "form12": {"metadata": {"recFormNo": "12", "versionNo": "16"}, "guideQuestions": {"informedConsentNecessity": {"ifNoExplanation": "", "necessaryToSeekConsent": "Yes"}, "sufficientInformationChecklist": {"purposeOfStudy": "Yes", "otherConcernsComments": "Informed consent fails to guarantee institutional coverage for psychiatric hospitalization expenses incurred due to research-related adverse medication events.", "benefitsToParticipants": "Yes", "extentOfConfidentiality": "No", "proceduresToBeCarriedOut": "Yes", "discomfortsAndInconveniences": "Yes", "risksIncludingDiscrimination": "No", "expectedDurationOfParticipation": "Yes", "alternativeTreatmentsOrProcedures": "Not Applicable", "randomAssignmentToTrialTreatments": "Not Applicable", "adequateProcessForVoluntaryConsent": "No", "refusalOrDiscontinuanceWithoutPenalty": "Yes", "writtenInSimpleUnderstandableLanguage": "No", "compensationOrMedicalTreatmentsForInjury": "No", "contactPersonForQuestionsAndInjuryAssistance": "Yes"}}, "recommendations": {"decision": "Disapproved", "disapprovedReasons": "Informed consent severely understates medication risks and fails to provide clinical injury coverage.", "majorRevisionComments": "", "minorRevisionsComments": ""}}}', 1),
