    (6, 109, 2, 1, 'Finalized', 'Major Revisions', 'The Full Committee convened on October 14, 2026. The committee commended the strong clinical premise and public health relevance to diabetic neuropathy care in Western Mindanao. However, ethical clearance is withheld pending protocol restructuring to address: (1) independent DSMB establishment with predefined stopping rules, (2) submission of FDA Philippines Certificate of Product Registration or Clinical Trial Exemption for the botanical extract, and (3) bilingual informed consent revision with explicit details on injury insurance coverage.', '1. Establish an independent Data and Safety Monitoring Board (DSMB) with formal charter, external medical monitor, and stopping rules independent of the study sponsor.
2. Submit FDA Philippines Clinical Trial Approval (CTA) or Certificate of Product Registration (CPR) for the standardized Morinda citrifolia botanical formulation.
3. Revise the Informed Consent Form to include a simplified local dialect translation (Tausug/Chavacano) and explicitly stipulate institutional compensation for study-related injuries.
4. Submit the revised protocol and point-by-point clarification matrix within thirty (30) calendar days.', '2026-10-14', '{"f11_socialValue": {"finding": "Satisfactory", "remarks": "High clinical relevance to diabetic complications in Western Mindanao.", "is_modified": false}, "f11_scientificValidity": {"finding": "Satisfactory", "remarks": "Randomized, double-blind methodology is statistically sound.", "is_modified": false}, "f11_risksToParticipants": {"finding": "Requires Modification", "remarks": "Establish an independent Data and Safety Monitoring Board (DSMB) with formal charter, external medical monitor, and stopping rules.", "is_modified": false}, "f11_fairSubjectSelection": {"finding": "Satisfactory", "remarks": "Inclusion and exclusion criteria are well-balanced.", "is_modified": false}, "f11_riskMitigationMeasures": {"finding": "Requires Modification", "remarks": "Submit FDA Philippines Clinical Trial Approval or CPR documentation for the standardized botanical formulation.", "is_modified": false}, "f12_voluntaryParticipation": {"finding": "Satisfactory", "remarks": "Voluntary nature and unconditional withdrawal rights are clear.", "is_modified": false}, "f12_writtenInSimpleUnderstandableLanguage": {"finding": "Requires Modification", "remarks": "Simplify the Informed Consent Form with bilingual translation (English & Chavacano/Tausug) and explicitly detail study injury compensation coverage.", "is_modified": false}}', '[{"issue": "Reviewers noted lack of formal independent safety monitoring board and stopping rules for botanical adverse effects.", "status": "Pending", "source_form": "Form 11", "directive_id": "dir-f11_risksToParticipants", "is_mandatory": true, "criterion_key": "risksToParticipants", "criterion_label": "Are there risks / probable harms to the human participants in the study?", "required_action": "Establish an independent Data and Safety Monitoring Board (DSMB) with formal charter, external medical monitor, and stopping rules."}, {"issue": "Lack of FDA Philippines Certificate of Product Registration or CTA documentation for the active extract.", "status": "Pending", "source_form": "Form 11", "directive_id": "dir-f11_riskMitigationMeasures", "is_mandatory": true, "criterion_key": "riskMitigationMeasures", "criterion_label": "Are there measures to mitigate the risks?", "required_action": "Submit FDA Philippines Clinical Trial Approval / CPR or official exemption certificate for the standardized botanical formulation."}, {"issue": "Consent form exceeds recommended reading level and lacks study injury compensation clause.", "status": "Pending", "source_form": "Form 12", "directive_id": "dir-f12_writtenInSimpleUnderstandableLanguage", "is_mandatory": true, "criterion_key": "writtenInSimpleUnderstandableLanguage", "criterion_label": "Written in simple and understandable language?", "required_action": "Simplify the Informed Consent Form with bilingual translation (English & Chavacano/Tausug) and explicitly detail medical coverage and compensation for research-related adverse events."}]', '{"fair_subject_selection": true, "informed_consent_clarity": false, "vulnerability_safeguards": true, "social_and_scientific_value": true, "favorable_risk_benefit_ratio": false, "all_flagged_criteria_resolved": false}', '[]', NULL, '2026-10-18 13:51:28.349557+00', '2026-10-18 13:51:28.349557+00', '2026-10-15 14:00:00+00'),
    (7, 106, 1, 1, 'Draft', 'Minor Revisions', '', '', '2026-10-26', '{"f11_socialValue": {"finding": "Satisfactory", "remarks": "Satisfactory; criteria met without revisions.", "is_modified": false}, "f12_purposeOfStudy": {"finding": "Satisfactory", "remarks": "Satisfactory; criteria met without revisions.", "is_modified": false}, "f11_vulnerabilityIssue": {"finding": "Satisfactory", "remarks": "Satisfactory; criteria met without revisions.", "is_modified": false}, "f11_risksToParticipants": {"finding": "Requires Modification", "remarks": "Reviewers divided. Revisions required: Primary Reviewer: Risks of adverse psychotropic reactions are minimal to moderate, managed by weekly telephonic check-ins.; Maria Santos: Remote prescribing of scheduled psychotropics without local psychiatric emergency facility partnership poses imminent patient safety hazard.", "is_modified": false}, "f11_otherConcernsComment": {"finding": "Requires Modification", "remarks": "Excellent community initiative. Recommend ethical approval.; Unacceptable participant risks without a dedicated field psychiatrist.", "is_modified": false}, "f11_studyObjectivesSmart": {"finding": "Satisfactory", "remarks": "Satisfactory; criteria met without revisions.", "is_modified": false}, "f12_otherConcernsComments": {"finding": "Requires Modification", "remarks": "Consent forms are clearly worded and respectful of cultural sensitivities.; Informed consent fails to guarantee institutional coverage for psychiatric hospitalization expenses incurred due to research-related adverse medication events.; Tele-mental health consent must be adapted for low-literacy participants. Provide audio-visual or pictorial consent explanation in Sinama/Tausug and clarify cloud server data encryption standards.", "is_modified": false}, "f11_riskMitigationMeasures": {"finding": "Requires Modification", "remarks": "Reviewers divided. Revisions required: Primary Reviewer: Local MHO transport referral pathways provide acceptable safety 